catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }
    var book_author = g_form.getValue('book');
    console.log("book author name", book_author);
    var ga = new GlideAjax('CheckAvailability');
    ga.addParam('sysparm_name', 'checkAvailabilityOfBook');
    ga.addParam('sysparm_book_sys_id', book_author);
    ga.getXMLAnswer(showAlertIfNotAvailable);

    function showAlertIfNotAvailable(response) {
        console.log("-----toggle------");
        var jsonObj = JSON.parse(response);
        console.log("--response---", jsonObj);
        if (!jsonObj.is_available) {

            var nearestReturnDate = jsonObj.nearestReturnDate;
            if (nearestReturnDate) {

                g_form.addErrorMessage('Book is currently not available. Next available date: ' + jsonObj.nearestReturnDate);
            } else {
                g_form.addErrorMessage('Book is currently not available.');
            }

        }
    }

    function toggleSubmitButton(enable) {
        var submitButton = document.querySelector('button[id="submit-btn"]');
        if (submitButton) {
            submitButton.disabled = !enable;
        }
   }

    //Type appropriate comment here, and begin script below

}
